define({"topics":[{"title":"Powering down the ICN from root level","shortdesc":"<p class=\"shortdesc\">If the application's software is down, you can power down the ICNs by using command line at the root level.<\/p>","href":"t_PoweringDownTheICNFromRootLevel_4.html","attributes":{"data-id":"id_2003032"},"menu":{"hasChildren":false},"tocID":"id_2003032-d46e164947","topics":[]},{"title":"Powering off the ICN manually","shortdesc":"<p class=\"shortdesc\">If the preferred shutdown method does not work, a last resort is to use the ICN power button.<\/p>","href":"t_PowerOffICNsManually_4.html","attributes":{"data-id":"id_2003033"},"menu":{"hasChildren":false},"tocID":"id_2003033-d46e165051","topics":[]}]});